style.css:
@-moz-document domain("bandlab.com") {
/* Background */
  body {
    background-color: #ffe6f0 !important; /* light pink */
    color: #3a3a3a !important; /* dark grey text for readability */
  }

  /* Headers / Top Bar */
  header, .top-bar, .navbar, .header {
    background-color: #ff99cc !important; /* bright pink */
    color: white !important;
  }

  /* Buttons */
  button, .btn, .primary-btn {
    background-color: #ff66b2 !important;
    border-color: #ff66b2 !important;
    color: white !important;
  }
  button:hover, .btn:hover, .primary-btn:hover {
    background-color: #ff3385 !important; /* darker hover pink */
  }

  /* Panels & Cards */
  .card, .panel, .sidebar, .workspace, .content {
    background-color: #fff0f5 !important; /* lavender blush */
    border: 1px solid #ff99cc !important;
  }

  /* Links */
  a {
    color: #ff4da6 !important;
  }
  a:hover {
    color: #e60073 !important;
  }
}
